// Selects one sending batch from the CRM and builds the Instantly payload.
// POST body: { campaignId, route, limit, namedOnly, apply }
//   campaignId  required to actually push
//   route       default 'A-lite'
//   limit       default 250   (Instantly caps a single request at 1000)
//   namedOnly   default true  - only contacts whose email is a real person
//   apply       default false - DRY RUN, nothing pushed and nothing written
//
// Marks pushed rows Status='queued' so the next batch never overlaps. We track
// this in OUR sheet rather than relying on Instantly state.
try {
  var body = {};
  try { body = $('Run').first().json.body || {}; } catch (e0) { }
  var campaignId = body.campaignId || '';
  var route = body.route || 'A-lite';
  var limit = Math.min(Number(body.limit) || 250, 1000);
  var namedOnly = body.namedOnly !== false;
  var apply = body.apply === true;

  var v = ($input.first().json || {}).values || [];
  if (v.length < 2) { return [{ json: { error: 'Sheet read returned no rows' } }]; }
  var H = v[0], I = {};
  for (var h = 0; h < H.length; h++) { I[String(H[h]).trim()] = h; }
  function c(r, n) { var i = I[n]; if (i === undefined) { return ''; } var x = r[i]; return (x === undefined || x === null) ? '' : String(x).trim(); }
  function T(x) { var s = String(x).toLowerCase(); return s === 'true' || s === 'yes' || s === '1'; }
  function colLetter(n) { var s = ''; var x = n + 1; while (x > 0) { var m = (x - 1) % 26; s = String.fromCharCode(65 + m) + s; x = Math.floor((x - 1) / 26); } return s; }

  var GEN = ['info','sales','enquiries','enquiry','admin','contact','hello','office','accounts','mail','support','team','service','post','general','bookings','booking','reception','help','hi'];
  function isNamedPerson(e) {
    var s = String(e || '');
    var a = s.indexOf('@');
    if (a < 1) { return false; }
    var lp = s.substring(0, a).toLowerCase();
    for (var i = 0; i < GEN.length; i++) { if (lp === GEN[i]) { return false; } }
    return /^[a-z]{2,14}([._-][a-z]{2,14})?$/.test(lp);
  }

  var sIdx = I['Status'];
  if (sIdx === undefined) { return [{ json: { error: 'Status column not found' } }]; }

  var rows = v.slice(1);
  var leads = [], statusCol = [], picked = 0;
  var skipped = { notSendReady: 0, wrongRoute: 0, alreadyQueued: 0, roleInbox: 0, overLimit: 0 };

  for (var r = 0; r < rows.length; r++) {
    var row = rows[r];
    var status = c(row, 'Status');
    var take = false;

    if (c(row, 'Email') === '' || T(c(row, 'PECR Risk')) || !T(c(row, 'Emailable'))) { skipped.notSendReady++; }
    else if (status !== 'new') { skipped.alreadyQueued++; }
    else if (c(row, 'Template Route') !== route) { skipped.wrongRoute++; }
    else if (namedOnly && !isNamedPerson(c(row, 'Email'))) { skipped.roleInbox++; }
    else if (picked >= limit) { skipped.overLimit++; }
    else { take = true; }

    if (take) {
      picked++;
      var site = c(row, 'Website');
      if (site && site.indexOf('http') !== 0) { site = 'https://' + site; }
      leads.push({
        email: c(row, 'Email'),
        first_name: c(row, 'First Name'),
        company_name: c(row, 'Company Name'),
        website: site,
        // Keys match the CRM headers EXACTLY - Instantly variables are case and
        // space sensitive, per the playbook's field map.
        custom_variables: {
          'City': c(row, 'City'),
          'Trade': c(row, 'Trade'),
          'Trade Scene': c(row, 'Trade Scene'),
          'Top Complaint': c(row, 'Top Complaint'),
          'Best Review Quote': c(row, 'Best Review Quote'),
          'Top Competitor': c(row, 'Top Competitor'),
          'Competitor Reviews': c(row, 'Competitor Reviews'),
          'Review Count': c(row, 'Review Count'),
          'Review Gap': c(row, 'Review Gap'),
          'Closing Time': c(row, 'Closing Time'),
          'Template Route': c(row, 'Template Route'),
          'Email 2 Route': c(row, 'Email 2 Route')
        }
      });
      statusCol.push(['queued']);
    } else {
      statusCol.push([status]);
    }
  }

  var payload = {
    campaign_id: campaignId,
    leads: leads,
    skip_if_in_campaign: true,
    skip_if_in_workspace: true,
    verify_leads_on_import: true
  };

  return [{ json: {
    apply: apply && campaignId !== '' && leads.length > 0,
    mode: apply ? (campaignId ? 'APPLY' : 'BLOCKED - no campaignId supplied') : 'DRY RUN - nothing pushed, nothing written',
    route: route,
    namedOnly: namedOnly,
    selected: leads.length,
    skipped: skipped,
    sampleLead: leads.length ? leads[0] : null,
    _payload: payload,
    _statusRange: "'Outreach CRM'!" + colLetter(sIdx) + '2:' + colLetter(sIdx) + (rows.length + 1),
    _statusValues: statusCol
  }}];
} catch (e) { return [{ json: { error: 'Select Batch failed: ' + e.message } }]; }

// Strips the bulky payload out of the response.
try {
  var b = $('Select Batch').first().json;
  var pushed = null, marked = null;
  try { var p = $('Push to Instantly').first().json; if (p) { pushed = p.error ? { error: p.error } : p; } } catch (e1) { }
  try { var m = $('Mark Queued in CRM').first().json; if (m && m.updatedCells !== undefined) { marked = { range: m.updatedRange, cells: m.updatedCells }; } else if (m && m.error) { marked = { error: m.error }; } } catch (e2) { }

  return [{ json: {
    mode: b.mode,
    route: b.route,
    namedOnly: b.namedOnly,
    selected: b.selected,
    skipped: b.skipped,
    sampleLead: b.sampleLead,
    instantlyResponse: pushed || 'not attempted (dry run)',
    crmStatusWrite: marked || 'not attempted (dry run)',
    error: b.error || null
  }}];
} catch (e) { return [{ json: { error: 'Report failed: ' + e.message } }]; }
